def train_step(model, optimizer, x, y):
  loss_fn = lambda model: ((model(x) - y) ** 2).mean()
  loss, grads = nnx.value_and_grad(loss_fn)(model)
  optimizer.update(model, grads)  # in-place updates
  return loss

